from pathlib import Path
import re


def must_replace(text, old, new, name):
    if old not in text:
        raise SystemExit(f'Missing expected {name} block')
    return text.replace(old, new, 1)


def sub(text, pattern, replacement, name):
    out, count = re.subn(pattern, lambda _: replacement, text, count=1, flags=re.S)
    if count != 1:
        raise SystemExit(f'Missing expected {name} block')
    return out

