checkout = r'''function Checkout({cart,setPage,products,offers,setCompletedOrder}){const[error,setError]=useState('');return <main className="checkout"><div className="checkoutbox"><p className="eyebrow">SAFA / CHECKOUT</p><h1>Complete your ritual.</h1><p className="field-legend"><FieldMark required/> Required <FieldMark/> Optional</p><form onSubmit={async e=>{e.preventDefault();setError('');const f=e.currentTarget;const phone1=f.phone1.value.replace(/\D/g,'');const phone2=f.phone2.value.replace(/\D/g,'');if(phone1===phone2){setError('The two phone numbers must be different.');return}const data={customerName:f.name.value.trim(),phone1,phone2,governorate:f.governorate.value,address:f.address.value.trim(),buildingNumber:f.building.value.trim(),apartmentNumber:f.apartment.value.trim(),items:cart.map(p=>({productId:p.id,quantity:Number(p.quantity||1),selectedSpecification:p.selectedSpecification||''}))};const r=await api('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const x=await r.json().catch(()=>({}));if(!r.ok){setError(x.error||'Order could not be placed');return}setCompletedOrder({order:x,purchased:[...cart]});setPage('confirmation')}}><label>Full name <FieldMark required/><input name="name" required autoComplete="name"/></label><label>Phone number <FieldMark required/><input name="phone1" required type="tel" inputMode="tel" autoComplete="tel"/></label><label>Second phone number <FieldMark required/><input name="phone2" required type="tel" inputMode="tel" autoComplete="tel-national"/></label><label>Governorate <FieldMark required/><select name="governorate" required defaultValue=""><option value="" disabled>Select governorate</option>{EGYPT_GOVERNORATES.map(g=><option key={g} value={g}>{g}</option>)}</select></label><label>Address <FieldMark required/><textarea name="address" required autoComplete="street-address"></textarea></label><div className="twofields"><label>Building number <FieldMark/><input name="building" inputMode="numeric"/></label><label>Apartment number <FieldMark/><input name="apartment" inputMode="numeric"/></label></div>{error&&<p className="error checkout-error">{error}</p>}<button className="goldbtn">CONFIRM ORDER ↗</button></form></div></main>}'''
