s = must_replace(s, "CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE SET NULL,product_name_snapshot text NOT NULL,price_snapshot numeric(12,2) NOT NULL,quantity int NOT NULL,discount_snapshot numeric(12,2) DEFAULT 0,total numeric(12,2) NOT NULL);", "CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE SET NULL,product_name_snapshot text NOT NULL,price_snapshot numeric(12,2) NOT NULL,quantity int NOT NULL,discount_snapshot numeric(12,2) DEFAULT 0,total numeric(12,2) NOT NULL,selected_specification text DEFAULT '');", 'order_items table')
